declare const _default = "\n.playform-family-tab {\n  display: grid;\n  flex: 1;\n  gap: 12px;\n  align-content: start;\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 880px;\n  min-height: 0;\n  margin: 0 auto;\n  padding: 20px 16px 28px;\n  overflow: auto;\n}\n\n.playform-family-tab > p {\n  margin: 0;\n  padding: 24px 16px;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 13px;\n  line-height: 20px;\n  text-align: center;\n}\n\n.playform-family-section {\n  box-sizing: border-box;\n  background: var(--dsw-alias-settings-card-fill);\n  border: 0.5px solid var(--dsw-alias-settings-card-stroke);\n  border-radius: var(--dsw-radius-xl);\n  display: grid;\n  gap: 8px;\n  padding: 14px 16px 16px;\n}\n\n.playform-family-section h3 {\n  color: var(--dsw-alias-label-primary);\n  font-size: 13px;\n  font-weight: 600;\n  line-height: 18px;\n  margin: 0;\n}\n\n.playform-family-status {\n  color: var(--dsw-alias-label-secondary);\n  font-size: 11px;\n  font-weight: 500;\n  line-height: 16px;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin: 0;\n}\n\n.playform-family-status::before {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  corner-shape: round;\n  content: \"\";\n  flex: none;\n  background: var(--dsw-alias-state-idle-primary);\n}\n\n.playform-family-section[data-activation=enabled] .playform-family-status::before {\n  background: var(--dsw-alias-state-success-primary);\n}\n\n.playform-family-section[data-activation=unknown] .playform-family-status::before {\n  background: var(--dsw-alias-state-warn-primary);\n}\n\n.playform-family-tail {\n  display: grid;\n  gap: 2px;\n  margin: 0;\n  padding: 8px 10px;\n  max-height: 136px;\n  overflow: auto;\n  list-style: none;\n  color: var(--dsw-alias-label-secondary);\n  font-family: var(--ds-font-family-code, ui-monospace, SFMono-Regular, Menlo, monospace);\n  font-size: 11px;\n  line-height: 16px;\n  background: var(--dsw-alias-bg-layer-1);\n  border: 0.5px solid var(--dsw-alias-border-l1);\n  border-radius: var(--dsw-radius-md);\n}\n\n.playform-family-tail li {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.playform-family-tail li[data-kind=\"observe/stamp\"] {\n  color: var(--dsw-alias-brand-primary);\n}\n\n.playform-family-form {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n  gap: 10px 12px;\n  margin: 2px 0 0;\n}\n\n.playform-family-field {\n  display: grid;\n  gap: 4px;\n  min-width: 0;\n  color: var(--dsw-alias-label-primary);\n  font-size: 12px;\n  line-height: 16px;\n}\n\n.playform-family-field-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: var(--dsw-alias-label-secondary);\n}\n\n.playform-family-field input[type=text],\n.playform-family-field input[type=number],\n.playform-family-field select {\n  box-sizing: border-box;\n  width: 100%;\n  height: 28px;\n  padding: 0 8px;\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n  font-size: 12px;\n  background: var(--dsw-alias-bg-layer-1);\n  border: 0.5px solid var(--dsw-alias-border-l1);\n  border-radius: var(--dsw-radius-sm);\n  outline: none;\n}\n.playform-family-field input[type=text]:focus-visible,\n.playform-family-field input[type=number]:focus-visible,\n.playform-family-field select:focus-visible {\n  border-color: var(--dsw-alias-brand-primary);\n  outline: 2px solid var(--dsw-alias-brand-primary);\n  outline-offset: 1px;\n}\n\n.playform-family-field input[type=checkbox] {\n  width: 14px;\n  height: 14px;\n  margin: 2px 0 0;\n  accent-color: var(--dsw-alias-brand-primary);\n}\n\n.playform-family-field-override {\n  padding: 1px 7px;\n  color: var(--dsw-alias-brand-primary);\n  font-size: 10px;\n  font-weight: 500;\n  line-height: 14px;\n  background: var(--dsw-alias-bg-layer-1);\n  border: 0.5px solid var(--dsw-alias-border-l2);\n  border-radius: 999px;\n  corner-shape: round;\n  justify-self: start;\n}\n\n.playform-family-field-secret {\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  font-style: italic;\n}\n\n.playform-family-form-note {\n  margin: 0;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 18px;\n}\n\n.playform-family-overlay {\n  box-sizing: border-box;\n  display: grid;\n  gap: 12px;\n  width: 100%;\n  max-height: 80vh;\n  padding: 20px;\n  overflow: auto;\n  background: var(--dsw-alias-bg-overlay);\n  border: 0;\n  border-radius: var(--dsw-radius-panel);\n  box-shadow: var(--dsw-elevation-panel);\n}\n\n.playform-family-overlay:not(:has(.playform-family-section)) {\n  display: none;\n}";
